// ================================================================================================
// [Phase 4, P0.4] The EIP-7851 gap: helpers
// ================================================================================================
//
// Env (set by run_p04.sh): P04_RUN, P04_REWRITE_FILE (the proxy's rewrite table), P04_ARTIFACTS (forge artifacts of
// MLDSA44Verifier, MLDSA44Account1271, NoErc1271), P04_F1600_HEX (the verifier's Keccak-f1600 helper runtime),
// P04_MLDSA_PY / P04_MLDSA_TOOL / P04_MLDSA_REPO (E4's ML-DSA-44 signer and the upstream checkout it imports).

/// keccak256 of the Keccak-f1600 helper runtime the ML-DSA-44 verifier pins (upstream helpers/f1600_170.hex).
const P04_F1600_CODEHASH: B256 =
    b256!("4afb4435879cdf8e50474c7aab2bc3a679caed432550ad6dba64f509309a817b");
/// E4's public local test seed: keccak256 of this string. Test-only; never used on a public network.
const P04_MLDSA_SEED_LABEL: &[u8] = b"fhe-authority-lifecycle/E4/local-test-seed/v1";

fn p04_run() -> String {
    std::env::var("P04_RUN").unwrap_or_else(|_| "r1".to_string())
}

/// E4's ML-DSA-44 signer (`mldsa_tool.py`): the upstream repository's key derivation and FIPS 204 signing.
#[derive(Clone)]
struct P04Mldsa {
    py: String,
    tool: PathBuf,
    repo: PathBuf,
}

impl P04Mldsa {
    fn load() -> anyhow::Result<Self> {
        Ok(Self {
            py: env("P04_MLDSA_PY")?,
            tool: PathBuf::from(env("P04_MLDSA_TOOL")?),
            repo: PathBuf::from(env("P04_MLDSA_REPO")?),
        })
    }

    /// One tool call; the seed goes to the child through its environment only.
    fn call(&self, args: &[&str]) -> anyhow::Result<serde_json::Value> {
        let out = std::process::Command::new(&self.py)
            .arg("-I")
            .arg("-B")
            .arg(&self.tool)
            .arg("--repo")
            .arg(&self.repo)
            .args(args)
            .env_clear()
            .env("PATH", std::env::var("PATH").unwrap_or_default())
            .env("MLDSA44_SEED_HEX", hex::encode(keccak256(P04_MLDSA_SEED_LABEL)))
            .output()?;
        ensure!(
            out.status.success(),
            "mldsa_tool {} failed: {}",
            args[0],
            String::from_utf8_lossy(&out.stderr)
        );
        Ok(serde_json::from_slice(&out.stdout)?)
    }

    /// (pk, pk blob): the 1,312-byte public key and the verifier's 20,545-byte prepared form.
    fn pubkey(&self) -> anyhow::Result<(Vec<u8>, Vec<u8>)> {
        let v = self.call(&["pubkey"])?;
        let get = |k: &str| -> anyhow::Result<Vec<u8>> {
            Ok(hex::decode(v[k].as_str().ok_or_else(|| anyhow!("{k} missing"))?)?)
        };
        Ok((get("pk")?, get("blob")?))
    }

    /// A 2,420-byte ML-DSA-44 signature of the 32-byte digest, checked by the tool before it returns.
    fn sign(&self, digest: B256) -> anyhow::Result<Vec<u8>> {
        let v = self.call(&["sign", "--msg", &format!("{digest}")])?;
        ensure!(v["self_verified"] == true, "mldsa_tool: signature did not self-verify");
        let sig = hex::decode(v["sig"].as_str().ok_or_else(|| anyhow!("sig missing"))?)?;
        ensure!(sig.len() == 2420, "unexpected ML-DSA-44 signature length {}", sig.len());
        Ok(sig)
    }
}

/// The proxy's eth_getCode rewrite table: `0xef0101 ‖ delegate` for each (account, delegate).
fn p04_set_rewrite(entries: &[(Address, Address)]) -> anyhow::Result<()> {
    let mut table = serde_json::Map::new();
    for (account, delegate) in entries {
        let mut code = vec![0xef, 0x01, 0x01];
        code.extend_from_slice(delegate.as_slice());
        table.insert(format!("{account:#x}"), serde_json::Value::String(format!("0x{}", hex::encode(code))));
    }
    std::fs::write(env("P04_REWRITE_FILE")?, serde_json::Value::Object(table).to_string())?;
    Ok(())
}

/// A real EIP-7702 delegation of `account` to `delegate`: anvil_setCode with `0xef0100 ‖ delegate` (anvil executes
/// it as a delegation), read back from the node itself.
async fn p04_delegate(acl: &AnvilAcl, account: Address, delegate: Address) -> anyhow::Result<()> {
    let mut indicator = vec![0xef, 0x01, 0x00];
    indicator.extend_from_slice(delegate.as_slice());
    let _: serde_json::Value = acl
        .provider
        .raw_request("anvil_setCode".into(), (account, Bytes::from(indicator.clone())))
        .await?;
    let code = acl.provider.get_code_at(account).await?;
    ensure!(code.to_vec() == indicator, "delegation of {account} not in place");
    Ok(())
}

struct P04Stack {
    verifier: Address,
    pk_blob: Address,
    account: Address,
    no_erc1271: Address,
}

/// E4's ML-DSA-44 stack (helper, Fireblocks verifier, pk blob, `MLDSA44Account1271`) and a NoErc1271 delegate.
async fn p04_deploy_stack(acl: &AnvilAcl, m: &P04Mldsa) -> anyhow::Result<P04Stack> {
    let artifacts = PathBuf::from(env("P04_ARTIFACTS")?);
    let provider = &acl.provider;
    let helper_hex: String = std::fs::read_to_string(env("P04_F1600_HEX")?)?.split_whitespace().collect();
    let helper_code = Bytes::from(hex::decode(helper_hex.trim_start_matches("0x"))?);
    ensure!(keccak256(&helper_code) == P04_F1600_CODEHASH, "f1600 helper does not hash to the verifier's pin");
    let helper = Address::from_slice(&rand_digest().0[..20]);
    let _: serde_json::Value = provider.raw_request("anvil_setCode".into(), (helper, helper_code)).await?;

    let verifier_art = load_artifact(&artifacts.join("MLDSA44Verifier.json"))?;
    let mut code = verifier_art.bytecode.to_vec();
    code.extend(helper.abi_encode());
    let verifier = deploy_code(provider, acl.owner, code, "MLDSA44Verifier deploy").await?;

    let (pk, blob) = m.pubkey()?;
    let pk_hash = keccak256(&pk);
    let pk_blob = Address::from_slice(&rand_digest().0[..20]);
    let _: serde_json::Value = provider.raw_request("anvil_setCode".into(), (pk_blob, Bytes::from(blob))).await?;

    let account_art = load_artifact(&artifacts.join("MLDSA44Account1271.json"))?;
    let mut code = account_art.bytecode.to_vec();
    code.extend((verifier, pk_blob, pk_hash).abi_encode_params());
    let account = deploy_code(provider, acl.owner, code, "MLDSA44Account1271 deploy").await?;

    let no_erc1271 = Address::from_slice(&rand_digest().0[..20]);
    let no_art = load_artifact(&artifacts.join("NoErc1271.json"))?;
    let _: serde_json::Value = provider
        .raw_request("anvil_setCode".into(), (no_erc1271, no_art.deployed_bytecode.clone()))
        .await?;
    info!(
        "P04-STACK helper={helper} verifier={verifier} pk_blob={pk_blob} pk_hash={pk_hash} \
        account=MLDSA44Account1271@{account} no_erc1271={no_erc1271}"
    );
    Ok(P04Stack { verifier, pk_blob, account, no_erc1271 })
}

/// One logged row; the mismatches are collected and the test fails at the end, after every row ran.
fn p04_log(
    tree: &str,
    label: &str,
    res: &anyhow::Result<RunResult>,
    expect: Outcome,
    wall_ms: u128,
    mismatches: &mut Vec<String>,
) {
    match res {
        Ok(rr) => {
            info!(
                "P04-RESULT label={label} version={VERSION} tree={tree} expected={expect:?} observed={:?} \
                kms_mock_hits={} error_counter={} error_code={} wall_ms={wall_ms}",
                rr.observed,
                rr.kms_hits,
                rr.error_counter.map(|e| e.to_string()).unwrap_or_else(|| "-".into()),
                rr.error_code.clone().unwrap_or_else(|| "-".into()),
            );
            let refused_ok = rr.observed == Outcome::Rejected && rr.kms_hits == 0;
            let forwarded_ok = rr.observed == Outcome::Forwarded && rr.kms_hits >= 2;
            if (expect == Outcome::Rejected && !refused_ok) || (expect == Outcome::Forwarded && !forwarded_ok) {
                mismatches.push(format!("{label}: expected {expect:?}, observed {:?} (kms hits {})", rr.observed, rr.kms_hits));
            }
        }
        Err(e) => {
            info!(
                "P04-RESULT label={label} version={VERSION} tree={tree} expected={expect:?} observed=HarnessError \
                kms_mock_hits=- error_counter=- error_code=- wall_ms={wall_ms} error=\"{e:#}\""
            );
            mismatches.push(format!("{label}: harness error {e:#}"));
        }
    }
}

// ================================================================================================
// [Phase 4, P1.1] E3, the KDA route: helpers
// ================================================================================================
//
// Env (set by run_p11.sh): P11_RUN; P11_MLDSA_PY / P11_MLDSA_TOOL / P11_MLDSA_REPO (dilithium-py signer for
// ML-DSA-44/65/87, the checkout whose `pythonref` it imports); and P0.4's P04_* for the ML-DSA-44 ERC-1271 stack.

/// K1, K2 tags (provisional in the draft), written out here so the test derives each KDA itself.
const P11_KDA_TAG: &[u8] = b"ERC-XXXX key-derived decryption signer v1";
const P11_SCHEME_TAG: &[u8] = b"ERC-XXXX native scheme:";
/// Public local test seeds: keccak256 of this prefix, the scheme and a key name. Test-only.
const P11_SEED_LABEL: &str = "fhe-authority-lifecycle/P1.1/local-test-seed/v1/";

fn p11_run() -> String {
    std::env::var("P11_RUN").unwrap_or_else(|_| "r1".to_string())
}

/// K1: the reserved verifierId of a native scheme.
fn p11_scheme_id(name: &str) -> Address {
    Address::from_slice(&keccak256([P11_SCHEME_TAG, name.as_bytes()].concat())[12..])
}

/// K2: the key-derived address of signerBytes.
fn p11_kda(signer_bytes: &[u8]) -> Address {
    Address::from_slice(&keccak256([P11_KDA_TAG, signer_bytes].concat())[12..])
}

/// dilithium-py ML-DSA-44/65/87 (`p11_mldsa_tool.py`).
#[derive(Clone)]
struct P11Signer {
    py: String,
    tool: PathBuf,
    repo: PathBuf,
}

impl P11Signer {
    fn load() -> anyhow::Result<Self> {
        Ok(Self {
            py: env("P11_MLDSA_PY")?,
            tool: PathBuf::from(env("P11_MLDSA_TOOL")?),
            repo: PathBuf::from(env("P11_MLDSA_REPO")?),
        })
    }

    /// One tool call; the seed goes to the child through its environment only.
    fn call(&self, seed: B256, args: &[&str]) -> anyhow::Result<serde_json::Value> {
        let out = std::process::Command::new(&self.py)
            .arg("-I")
            .arg("-B")
            .arg(&self.tool)
            .arg("--repo")
            .arg(&self.repo)
            .args(args)
            .env_clear()
            .env("PATH", std::env::var("PATH").unwrap_or_default())
            .env("MLDSA_SEED_HEX", hex::encode(seed))
            .output()?;
        ensure!(
            out.status.success(),
            "p11_mldsa_tool {} failed: {}",
            args[0],
            String::from_utf8_lossy(&out.stderr)
        );
        Ok(serde_json::from_slice(&out.stdout)?)
    }
}

/// One ML-DSA key of the test, with its signerBytes and KDA.
#[derive(Clone)]
struct P11Key {
    scheme: &'static str,
    seed: B256,
    signer_bytes: Vec<u8>,
    kda: Address,
    signer: P11Signer,
}

impl P11Key {
    fn new(signer: &P11Signer, scheme: &'static str, name: &str) -> anyhow::Result<Self> {
        let seed = keccak256(format!("{P11_SEED_LABEL}{scheme}/{name}"));
        let v = signer.call(seed, &["pubkey", "--scheme", scheme])?;
        let pk = hex::decode(v["pk"].as_str().ok_or_else(|| anyhow!("pk missing"))?)?;
        let signer_bytes = [p11_scheme_id(scheme).as_slice(), &pk[..]].concat();
        let kda = p11_kda(&signer_bytes);
        Ok(Self { scheme, seed, signer_bytes, kda, signer: signer.clone() })
    }

    /// Pure ML-DSA, empty context, over the 32-byte digest; checked by the tool before it returns.
    fn sign(&self, digest: B256) -> anyhow::Result<Vec<u8>> {
        let v = self.signer.call(self.seed, &["sign", "--scheme", self.scheme, "--msg", &format!("{digest}")])?;
        ensure!(v["self_verified"] == true, "p11_mldsa_tool: signature did not self-verify");
        Ok(hex::decode(v["sig"].as_str().ok_or_else(|| anyhow!("sig missing"))?)?)
    }
}

/// How a KDA request's signature field is made.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum P11Sig {
    /// abi.encode(signerBytes, sig over the request digest) (K4).
    Valid,
    /// The same shape, signed over another digest: does not verify (K6).
    OtherDigest,
    /// 65 bytes: an ECDSA signature by a fresh key (K5: never the route).
    Ecdsa65,
}

#[derive(Clone)]
struct P11Kda {
    key: P11Key,
    sig: P11Sig,
}

impl P11Kda {
    fn signature(&self, digest: B256) -> anyhow::Result<Vec<u8>> {
        let field = |sig: Vec<u8>| (Bytes::from(self.key.signer_bytes.clone()), Bytes::from(sig)).abi_encode_params();
        Ok(match self.sig {
            P11Sig::Valid => field(self.key.sign(digest)?),
            P11Sig::OtherDigest => field(self.key.sign(keccak256(digest))?),
            P11Sig::Ecdsa65 => PrivateKeySigner::from_bytes(&rand_digest())?.sign_hash_sync(&digest)?.as_bytes().to_vec(),
        })
    }
}

/// A KDA request: requester `requester` (default: the key's KDA), one entry owned by `owner`.
fn p11_kda_req(
    label: String,
    key: &P11Key,
    sig: P11Sig,
    requester: Option<Address>,
    owner: Address,
    http: bool,
    expect: Outcome,
) -> anyhow::Result<ReqV2> {
    // `signer` is not used for a KDA request; a fresh key fills the field.
    let unused = PrivateKeySigner::from_bytes(&rand_digest())?;
    let mut req = ReqV2::new(label, &unused, owner, vec![], http, expect, "-");
    let requester = requester.unwrap_or(key.kda);
    req.path = if owner == requester { "v2-kda-direct" } else { "v2-kda" };
    req.requester = Some(requester);
    req.kda = Some(P11Kda { key: key.clone(), sig });
    Ok(req)
}

/// One logged row; mismatches are collected and the test fails at the end, after every row ran. `code` is the
/// expected error code of a refusal (`-`: not checked). The harness reads the code back only for requests made over
/// HTTP; for event requests the log keeps the error counter (1: refused for good at the first attempt; the attempt
/// limit: retried).
#[allow(clippy::too_many_arguments)]
fn p11_log(
    tree: &str,
    label: &str,
    k8: &str,
    res: &anyhow::Result<RunResult>,
    expect: Outcome,
    code: &str,
    wall_ms: u128,
    mismatches: &mut Vec<String>,
) {
    match res {
        Ok(rr) => {
            let got_code = rr.error_code.clone().unwrap_or_else(|| "-".into());
            info!(
                "P11-RESULT label={label} version={VERSION} tree={tree} k8={k8} expected={expect:?} observed={:?} \
                kms_mock_hits={} error_counter={} error_code={got_code} expected_code={code} wall_ms={wall_ms}",
                rr.observed,
                rr.kms_hits,
                rr.error_counter.map(|e| e.to_string()).unwrap_or_else(|| "-".into()),
            );
            let refused_ok = rr.observed == Outcome::Rejected && rr.kms_hits == 0;
            let forwarded_ok = rr.observed == Outcome::Forwarded && rr.kms_hits >= 2;
            if (expect == Outcome::Rejected && !refused_ok) || (expect == Outcome::Forwarded && !forwarded_ok) {
                mismatches.push(format!("{label}: expected {expect:?}, observed {:?} (kms hits {})", rr.observed, rr.kms_hits));
            } else if expect == Outcome::Rejected && code != "-" && rr.http && got_code != code {
                mismatches.push(format!("{label}: expected error code {code}, observed {got_code}"));
            }
        }
        Err(e) => {
            info!(
                "P11-RESULT label={label} version={VERSION} tree={tree} k8={k8} expected={expect:?} \
                observed=HarnessError kms_mock_hits=- error_counter=- error_code=- expected_code={code} \
                wall_ms={wall_ms} error=\"{e:#}\""
            );
            mismatches.push(format!("{label}: harness error {e:#}"));
        }
    }
}

/// Revokes `delegate`'s delegation from the unlocked anvil account `delegator` for `contract` (K3: revoking the
/// delegation revokes the signer).
async fn p11_revoke(
    acl: &AnvilAcl,
    delegator: Address,
    delegate: Address,
    contract: Address,
    handle: B256,
) -> anyhow::Result<()> {
    let receipt = acl
        .instance()
        .revokeDelegationForUserDecryption(delegate, contract)
        .from(delegator)
        .send()
        .await?
        .get_receipt()
        .await?;
    ensure_success(receipt, "revokeDelegationForUserDecryption")?;
    let still = acl.instance().isHandleDelegatedForUserDecryption(delegator, delegate, contract, handle).call().await?;
    info!("P11-REVOKE delegator={delegator} delegate={delegate} contract={contract} delegated_after={still}");
    Ok(())
}

/// P1.1 on main, the UNMODIFIED worker: it fails closed on a KDA request. Account A (anvil account U, holds h)
/// delegates to the KDA of an ML-DSA-44 and an ML-DSA-65 key; their valid KDA requests are refused (`ecrecover`
/// cannot parse the field and the code-less KDA answers no ERC-1271 call). Control rows: an ECDSA request (Uk) and
/// the ML-DSA-44 ERC-1271 account are forwarded as usual (the account only with the Level 1 budget, see P0.4: the
/// unmodified 250,000 gas cap refuses it).
#[rstest]
#[timeout(Duration::from_secs(1800))]
#[tokio::test]
async fn p11_e3_unmodified() -> anyhow::Result<()> {
    let log_guard = init_tracing();
    let env = Env::load()?;
    let run = p11_run();
    let signer = P11Signer::load()?;
    let a = Accounts::load(&env).await?;
    let keys = LocalKeys::new()?;
    let acl = deploy_acl(&env, AclKind::Level0, a.owner).await?;
    let handle = make_handle(env.chain_id);
    setup_grants(&acl, &a, &keys, handle).await?;
    let k44 = P11Key::new(&signer, "ML-DSA-44", "a")?;
    let k65 = P11Key::new(&signer, "ML-DSA-65", "a")?;
    let exp = expiration()?;
    for k in [&k44, &k65] {
        acl.delegate(a.u, k.kda, acl.dapp, exp).await?;
    }
    info!("P11-ACCOUNTS A={} KDA44={} KDA65={}", a.u, k44.kda, k65.kda);

    let test_instance = TestInstanceBuilder::default()
        .with_tracing(Some(log_guard))
        .with_db(DbInstance::setup_external().await?)
        .build();
    let db = test_instance.db();
    let rh = RequestHarness::new(&env, &acl, AclKind::Level0, handle).await?;
    let cfg = RunCfg::harness();
    info!("P11-CONFIG version={VERSION} tree=unmodified run={run} max_attempts={}", cfg.max_attempts);
    let mut mismatches = Vec::new();
    let rows: Vec<(String, ReqV2, Outcome)> = vec![
        ("kda44.valid".into(), p11_kda_req(format!("p11.{run}.unmodified.kda44.valid"), &k44, P11Sig::Valid, None, a.u, false, Outcome::Rejected)?, Outcome::Rejected),
        ("kda44.valid.http".into(), p11_kda_req(format!("p11.{run}.unmodified.kda44.valid.http"), &k44, P11Sig::Valid, None, a.u, true, Outcome::Rejected)?, Outcome::Rejected),
        ("kda65.valid".into(), p11_kda_req(format!("p11.{run}.unmodified.kda65.valid"), &k65, P11Sig::Valid, None, a.u, false, Outcome::Rejected)?, Outcome::Rejected),
        ("ecdsa.uk.direct".into(), ReqV2::new(format!("p11.{run}.unmodified.ecdsa.uk.direct"), &keys.uk, keys.uk.address(), vec![], false, Outcome::Forwarded, "-"), Outcome::Forwarded),
    ];
    for (_, req, expect) in &rows {
        let started = Instant::now();
        let res = rh.run_v2(db, req, &cfg).await;
        p11_log("unmodified", &req.label, "-", &res, *expect, "-", started.elapsed().as_millis(), &mut mismatches);
    }
    info!("P11-SUMMARY version={VERSION} tree=unmodified run={run} mismatches={}", mismatches.len());
    ensure!(mismatches.is_empty(), "P1.1 rows differ from the expectation: {mismatches:#?}");
    Ok(())
}
